(function(){
  var LINE={ js:'//', ts:'//', go:'//', c:'//', java:'//', rust:'//', python:'#', ruby:'#', sh:'#', yaml:'#', yml:'#', bash:'#' };
  var BLOCKC={ js:['/*','*/'], ts:['/*','*/'], c:['/*','*/'], java:['/*','*/'], go:['/*','*/'], rust:['/*','*/'], css:['/*','*/'], html:['<!--','-->'], xml:['<!--','-->'] };
  function count(code, lang){
    lang=(lang||'js').toLowerCase();
    var src=String(code||'').replace(/\r?\n$/,'');
    if(src==='') return {value:{total:0, blank:0, comment:0, code:0}};
    var lines=src.split(/\r?\n/);
    var total=lines.length, blank=0, comment=0, codel=0;
    var inBlock=false;
    var bc=BLOCKC[lang];
    var lineC=LINE[lang];
    for(var i=0;i<lines.length;i++){
      var t=lines[i].trim();
      if(t===''){ blank++; continue; }
      if(inBlock){
        comment++;
        if(bc && t.indexOf(bc[1])>=0) inBlock=false;
        continue;
      }
      if(bc && t.indexOf(bc[0])>=0){
        comment++; inBlock=true;
        if(t.indexOf(bc[1])>=0) inBlock=false;
        continue;
      }
      if(lineC && t.indexOf(lineC)===0){ comment++; continue; }
      codel++;
    }
    return {value:{total:total, blank:blank, comment:comment, code:codel}};
  }
  var API={count:count};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__TokeiForge__=API;
})();
